const raw = String($('Project File Upload Form').first().json.sharepoint_links || '');
const links = raw.split(/[\s,]+/).map((l) => l.trim()).filter((l) => /^https?:\/\//i.test(l)).slice(0, 20);
return links.map((link) => ({ json: { link, share_id: 'u!' + Buffer.from(link, 'utf8').toString('base64').replace(/=+$/, '').replace(/\//g, '_').replace(/\+/g, '-') } }));

// Combine form uploads with files built from SharePoint, Jira, Trello and Confluence.
const form = $('Project File Upload Form').first();
const json = Object.assign({}, form.json);
const binary = Object.assign({}, form.binary || {});
const log = [];
const ran = (name) => { try { return $(name).all(); } catch (e) { return null; } };
const slug = (t) => String(t || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 60) || 'untitled';
const csvCell = (v) => { const t = v === null || v === undefined ? '' : String(v); return /[",\n]/.test(t) ? '"' + t.replace(/"/g, '""') + '"' : t; };
const toCsv = (rows) => { if (!rows.length) return ''; const cols = Object.keys(rows[0]); return [cols.join(',')].concat(rows.map((r) => cols.map((c) => csvCell(r[c])).join(','))).join('\n'); };
const stripHtml = (h) => String(h || '').replace(/<\/(p|h[1-6]|li|tr|div)>/gi, '\n').replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/\n{3,}/g, '\n\n').trim();
let n = 0;
const add = async (text, fileName, mime) => { binary['connector_' + (n++)] = await this.helpers.prepareBinaryData(Buffer.from(text, 'utf8'), fileName, mime); };

// SharePoint: downloaded files keep their real names
const spFiles = ran('Download SharePoint File');
if (spFiles) {
  const infos = ran('Get SharePoint File Info') || [];
  for (let i = 0; i < spFiles.length; i++) {
    const it = spFiles[i];
    const info = (infos[i] || {}).json || {};
    if (it.json && it.json.error || !it.binary || !it.binary.data) { log.push('SharePoint: could not download ' + (info.name || 'link ' + (i + 1)) + ' - ' + JSON.stringify((it.json || {}).error || info.error || 'no file returned').slice(0, 300)); continue; }
    const b = Object.assign({}, it.binary.data);
    const name = info.name || b.fileName || ('file-' + (i + 1));
    b.fileName = 'sharepoint-' + name;
    b.fileExtension = name.includes('.') ? name.split('.').pop().toLowerCase() : (b.fileExtension || '');
    binary['connector_' + (n++)] = b;
  }
}

// Jira: issues become a work-items CSV
const jira = ran('Get Jira Issues');
if (jira) {
  const key = String(json.jira_project_key || '').trim().toUpperCase();
  const ok = jira.map((i) => i.json).filter((j) => j && j.key);
  const err = jira.map((i) => i.json).find((j) => j && j.error);
  if (err) log.push('Jira (' + key + '): ' + JSON.stringify(err.error).slice(0, 300));
  if (ok.length) {
    const rows = ok.map((j) => { const f = j.fields || {}; return { issue_key: j.key, summary: f.summary || '', issue_type: (f.issuetype || {}).name || '', issue_status: (f.status || {}).name || '', status_category: ((f.status || {}).statusCategory || {}).name || '', assignee: (f.assignee || {}).displayName || '', priority: (f.priority || {}).name || '', due_date: f.duedate || '', labels: (f.labels || []).join('; '), created: f.created || '', updated: f.updated || '' }; });
    await add(toCsv(rows), 'jira-' + slug(key) + '-issues.csv', 'text/csv');
  } else if (!err) log.push('Jira (' + key + '): no issues found');
}

// Trello: board cards become a work-items CSV (list name = stage)
const trello = ran('Get Trello Board');
if (trello) {
  const board = (trello[0] || {}).json || {};
  if (board.error || !board.cards) log.push('Trello (' + (json.trello_board || '') + '): ' + JSON.stringify(board.error || 'board not returned').slice(0, 300));
  else {
    const lists = {}; (board.lists || []).forEach((l) => { lists[l.id] = l.name; });
    const rows = board.cards.map((c) => ({ card_id: c.idShort || c.id, card_name: c.name || '', list_stage: lists[c.idList] || '', due_date: c.due || '', due_complete: !!c.dueComplete, labels: (c.labels || []).map((l) => l.name || l.color).join('; '), last_activity: c.dateLastActivity || '', url: c.shortUrl || c.url || '', description: (c.desc || '').slice(0, 2000) }));
    if (rows.length) await add(toCsv(rows), 'trello-' + slug(board.name) + '-cards.csv', 'text/csv');
    else log.push('Trello (' + (board.name || '') + '): no open cards');
  }
}

// Confluence: one text file per page
const conf = ran('Get Confluence Pages');
if (conf) {
  const space = String(json.confluence_space_key || '').trim();
  let pages = 0;
  for (const it of conf) {
    const r = it.json || {};
    if (r.error) { log.push('Confluence (' + space + '): ' + JSON.stringify(r.error).slice(0, 300)); continue; }
    const c = r.content || r;
    const title = c.title || r.title;
    if (!title) continue;
    const body = stripHtml(((c.body || {}).storage || {}).value || r.excerpt || '');
    await add(title + '\n\n' + body, 'confluence-' + slug(space) + '-' + slug(title) + '.txt', 'text/plain');
    pages++;
  }
  if (!pages && !log.some((l) => l.startsWith('Confluence'))) log.push('Confluence (' + space + '): no pages found');
}

if (log.length) await add('Connector fetch log\n\n' + log.join('\n'), 'connector-fetch-log.txt', 'text/plain');
json.connector_files_added = n;
json.connector_issues = log;
return [{ json, binary }];

// One item per uploaded file, binary moved to "data", plus snapshot + freshness metadata.
const fnv = (buf, seed) => {
  let h = (seed === undefined ? 0x811c9dc5 : seed) >>> 0;
  for (let j = 0; j < buf.length; j++) { h ^= buf[j]; h = Math.imul(h, 0x01000193) >>> 0; }
  return h >>> 0;
};
const hex = (n) => n.toString(16).padStart(8, '0');
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const meta = items[i].json || {};
  const binary = items[i].binary || {};
  const keys = Object.keys(binary);
  const files = [];
  let snapshotHash = 0x811c9dc5;
  for (const key of keys) {
    const buf = await this.helpers.getBinaryDataBuffer(i, key);
    const b = binary[key];
    const name = b.fileName || key;
    snapshotHash = fnv(Buffer.from(name, 'utf8'), snapshotHash);
    snapshotHash = fnv(buf, snapshotHash);
    files.push({ key, b, name, size: buf.length, fingerprint: hex(fnv(buf)) });
  }
  const uploadedAt = meta.submittedAt || $now.toISO();
  const project = String(meta.project_name || 'project').trim();
  const slug = project.toUpperCase().replace(/[^A-Z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 30) || 'PROJECT';
  const provided = String(meta.source_snapshot_id || '').trim();
  const snapshotFingerprint = hex(snapshotHash);
  const snapshotId = provided || (slug + '-' + DateTime.fromISO(uploadedAt).toFormat('yyyyMMddHHmmss') + '-' + snapshotFingerprint);
  for (const f of files) {
    const ext = (f.name.includes('.') ? f.name.split('.').pop() : '').toLowerCase();
    const bin = Object.assign({}, f.b);
    // DOCX is a ZIP container; label it so the decompress step unpacks it.
    if (ext === 'docx' || ext === 'pptx') { bin.fileExtension = 'zip'; bin.mimeType = 'application/zip'; }
    out.push({
      json: {
        project_name: project,
        submitted_by: meta.submitted_by || '',
        source_snapshot_id: snapshotId,
        snapshot_id_source: provided ? 'provided' : 'generated',
        snapshot_fingerprint: snapshotFingerprint,
        data_as_of: meta.data_as_of || '',
        uploaded_at: uploadedAt,
        upload_channel: meta.formMode || 'form',
        file_name: f.name,
        file_extension: ext,
        mime_type: f.b.mimeType || '',
        file_size_bytes: f.size,
        file_fingerprint: f.fingerprint,
        files_in_upload: files.length
      },
      binary: { data: bin },
      pairedItem: { item: i }
    });
  }
}
return out;

const decode = (t) => t.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'");
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const binary = items[i].binary || {};
  const keys = Object.keys(binary);
  const docKey = keys.find((k) => binary[k].fileName === 'document.xml' && String(binary[k].directory || '').includes('word'))
    || keys.find((k) => binary[k].fileName === 'document.xml');
  const slideKeys = keys
    .filter((k) => /^slide\d+\.xml$/.test(binary[k].fileName || '') && !String(binary[k].directory || '').includes('_rels'))
    .sort((a, b) => parseInt(binary[a].fileName.replace(/\D/g, ''), 10) - parseInt(binary[b].fileName.replace(/\D/g, ''), 10));
  if (docKey) {
    const xml = (await this.helpers.getBinaryDataBuffer(i, docKey)).toString('utf8');
    const text = decode(xml.replace(/<w:tab[^>]*\/>/g, '\t').replace(/<\/w:p>/g, '\n').replace(/<[^>]+>/g, '')).replace(/\n{3,}/g, '\n\n').trim();
    out.push({ json: { text, extraction_status: 'extracted' }, pairedItem: { item: i } });
  } else if (slideKeys.length) {
    const parts = [];
    for (let n = 0; n < slideKeys.length; n++) {
      const xml = (await this.helpers.getBinaryDataBuffer(i, slideKeys[n])).toString('utf8');
      const body = decode(xml.replace(/<\/a:p>/g, '\n').replace(/<[^>]+>/g, '')).replace(/\n{2,}/g, '\n').trim();
      parts.push('--- Slide ' + (n + 1) + ' ---\n' + body);
    }
    out.push({ json: { text: parts.join('\n\n'), extraction_status: 'extracted' }, pairedItem: { item: i } });
  } else {
    out.push({ json: { text: '', extraction_status: 'office_text_not_found' }, pairedItem: { item: i } });
  }
}
return out;

// Combine the downloaded Drive files into one upload, shaped like a form submission.
const binary = {};
$input.all().forEach((item, i) => { if (item.binary && item.binary.data) binary['project_files_' + i] = item.binary.data; });
return [{
  json: {
    project_name: 'ABCDE Ltd AI Adoption',
    source_snapshot_id: '',
    data_as_of: $now.toFormat('yyyy-MM-dd'),
    submitted_by: 'Google Drive import',
    submittedAt: $now.toISO(),
    formMode: 'googleDrive'
  },
  binary
}];

